                            revision: number;
                            /** Format: date-time */
                            publishedAt: string | null;
                            /** Format: date-time */
                            archivedAt: string | null;
                            /** @description Lessons that are locked */
                            lockedCount: number;
                            /** @description Lessons that were moved or swapped by an admin (source MANUAL) */
                            manualEditCount: number;
                            /** Format: date-time */
                            createdAt: string;
                            /** Format: date-time */
                            updatedAt: string;
                            /**
                             * Format: uuid
                             * @description The version this was cloned from
                             */
                            clonedFromId: string;
                            clonedFromVersionNumber: number;
                            /** @enum {string} */
                            lockMode: "KEEP" | "ALL" | "NONE";
